 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the solid internal separator, vertical or horizontal.
    candidates = []
    for c in range(w):
        if 0 < c < w - 1 and len({grid[r][c] for r in range(h)}) == 1:
            candidates.append((abs(c - (w - 1) / 2), 'v', c))
    for r in range(h):
        if 0 < r < h - 1 and len(set(grid[r])) == 1:
            candidates.append((abs(r - (h - 1) / 2), 'h', r))
    _, axis, cut = min(candidates)
    if axis == 'v':
        a = [row[:cut] for row in grid]
        b = [row[cut + 1:] for row in grid]
    else:
        a, b = grid[:cut], grid[cut + 1:]
    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    base = next(iter(common)) if len(common) == 1 else Counter(x for row in a + b for x in row).most_common(1)[0][0]
    return [[3 if a[r][c] == b[r][c] else base for c in range(len(a[0]))]
            for r in range(len(a))]
